use std::collections::BTreeMap;use artifactum_core::{provider_error,AcquireContext,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{client,json,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct FigshareProvider;#[async_trait]impl ArtifactProvider for FigshareProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"figshare".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["figshare".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,list:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{if c.offline{return Err(provider_error("figshare","cannot resolve while offline"));}let id=r.reference.locator();let base=profile_value(c,"api_base").unwrap_or("https://api.figshare.com/v2").trim_end_matches('/');let response=client()?.get(format!("{base}/articles/{id}")).send().await.map_err(|e|provider_error("figshare",e))?;let v=json("figshare",response).await?;let selection=r.selection.compile()?;let mut files=Vec::new();for f in v.get("files").and_then(|v|v.as_array()).into_iter().flatten(){let name=f.get("name").and_then(|v|v.as_str()).ok_or_else(||provider_error("figshare","file missing name"))?;if !selection.matches(name){continue}let url=f.get("download_url").and_then(|v|v.as_str()).ok_or_else(||provider_error("figshare","file missing download_url"))?;let mut digests=artifactum_core::DigestSet::default();if let Some(md5)=f.get("supplied_md5").and_then(|v|v.as_str()){digests.0.insert("md5".into(),md5.into());}files.push(ResolvedFile{path:ArtifactPath::new(name)?,size:f.get("size").and_then(|v|v.as_u64()),digests,media_type:None,source:serde_json::json!({"url":url})});}let rev=v.get("version").and_then(|v|v.as_u64()).map(|n|n.to_string()).or_else(||Some(id.into()));Ok(Resolution{provider:"figshare".into(),canonical_ref:format!("figshare:{id}"),revision:rev.map(|id|ResolvedRevision{id,requested:r.revision.clone()}),files,provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,_:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("figshare","missing download URL"))?;Ok(plan(url,Default::default()))}}
pub fn provider()->FigshareProvider{FigshareProvider}
